from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import ExpoURI


class ExpoV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def start_data_export(self, timeout=60, **kwargs):
        uri = ExpoURI().export_uri
        if kwargs.get("select"):
            kwargs["select"] = ','.join(kwargs["select"])
        return self.api_client.send_post_request(uri=uri, params=kwargs, timeout=timeout)

    def get_export_task_status(self, task_id, timeout=60):
        uri = ExpoURI().export_status_uri + f"?id={task_id}"
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def download_exported_data(self, task_id, file_path, timeout=60):
        uri = ExpoURI().export_result_uri + f"?id={task_id}"
        response = self.api_client.send_get_request(uri=uri, timeout=timeout, raw_response=True)
        with open(file_path, 'wb') as file:
            for chunk in response.iter_content(chunk_size=8192):
                file.write(chunk)
